/** Normalize every untrusted email and compute the daily counter key. */
return $input.all().map((item, index) => {
  const mail = item.json;
  const from = mail.from?.value?.[0] || {};
  const body = String(mail.text || mail.textPlain || mail.html || mail.textHtml || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 12000);
  return {
    json: {
      senderName: from.name || from.address || String(mail.from || '').replace(/<.*$/, '').trim() || 'External stakeholder',
      senderEmail: from.address || String(mail.from || '').match(/<([^>]+)>/)?.[1] || '',
      subject: String(mail.subject || 'Untitled request').slice(0, 250),
      body,
      messageId: mail.messageId || '',
      receivedAt: mail.date || new Date().toISOString(),
      dayKey: new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Zurich' })
    },
    pairedItem: { item: index }
  };
});

/** Validate the model response and build the Firebase ticket schema. */
const source = $('Normalize email').item.json;
const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let ai;
try { ai = JSON.parse(raw); } catch { throw new Error('Gemini returned invalid JSON'); }
const categories = ['User Story', 'Technical Task'];
const priorities = ['Urgent', 'Medium', 'Low'];
if (!ai.title || !categories.includes(ai.category) || !priorities.includes(ai.priority)) throw new Error('Gemini response failed schema validation');
const deadline = /^\d{4}-\d{2}-\d{2}$/.test(ai.due_date || '') ? ai.due_date : '';
const subtasks = Array.isArray(ai.subtasks)
  ? ai.subtasks.map((item) => ({ title: String(typeof item === 'string' ? item : item?.title || '').trim().slice(0, 200), done: false })).filter((item) => item.title).slice(0, 5)
  : [];
return [{ json: { title: String(ai.title).slice(0, 120), description: String(ai.description || source.body).slice(0, 4000), due_date: deadline, priority: ai.priority, assigned_contacts: [], category: ai.category, subtasks, column: 'triage', default_task: false, source: 'email', createdVia: 'email', isAiGenerated: true, ai_generated: true, creator: { type: 'external', name: source.senderName, email: source.senderEmail }, created_at: new Date().toISOString(), external_message_id: source.messageId } }];
